cat > hello/graphql.ts << 'EOF'
import { api } from "encore.dev";
import type { IncomingMessage, ServerResponse } from "node:http";
import {
  GraphQLSchema,
  GraphQLObjectType,
  GraphQLString,
  graphql,
  parse,
} from "graphql";

const schema = new GraphQLSchema({
  query: new GraphQLObjectType({
    name: "Query",
    fields: {
      hello: {
        type: GraphQLString,
        args: {
          name: { type: GraphQLString },
        },
        resolve: (_root, args: { name?: string | null }) => {
          const name = args.name ?? "World";
          return `Hello, ${name}!`;
        },
      },
    },
  }),
});

async function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    req.on("data", (chunk: Buffer) => chunks.push(chunk));
    req.on("end", () => resolve(Buffer.concat(chunks).toString("utf8")));
    req.on("error", reject);
  });
}

interface GraphQLPayload {
  query?: string;
  operationName?: string | null;
  variables?: Record<string, unknown> | null;
}

export const graphql = api.raw(
  { expose: true, method: "*", path: "/graphql" },
  async (req: IncomingMessage, resp: ServerResponse) => {
    try {
      let payload: GraphQLPayload;
      if (req.method === "GET") {
        const url = new URL(req.url ?? "/graphql", "http://localhost");
        const query = url.searchParams.get("query");
        const operationName = url.searchParams.get("operationName");
        const variablesParam = url.searchParams.get("variables");
        payload = {
          query: query ?? undefined,
          operationName: operationName ?? null,
          variables: variablesParam ? JSON.parse(variablesParam) : null,
        };
      } else {
        const body = await readBody(req);
        const contentType = (req.headers["content-type"] ?? "") as string;
        if (contentType.includes("application/graphql")) {
          payload = { query: body };
        } else {
          payload = JSON.parse(body) as GraphQLPayload;
        }
      }

      if (!payload.query) {
        resp.statusCode = 400;
        resp.setHeader("Content-Type", "application/json");
        resp.end(JSON.stringify({ errors: [{ message: "Missing query" }] }));
        return;
      }

      // Validate by parsing (catches syntax errors early).
      parse(payload.query);

      const result = await graphql({
        schema,
        source: payload.query,
        variableValues: payload.variables ?? undefined,
        operationName: payload.operationName ?? undefined,
      });

      resp.statusCode = 200;
      resp.setHeader("Content-Type", "application/json");
      resp.end(JSON.stringify(result));
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      resp.statusCode = 400;
      resp.setHeader("Content-Type", "application/json");
      resp.end(
        JSON.stringify({
          errors: [{ message }],
        })
      );
    }
  }
);
EOF

